using System.ComponentModel.DataAnnotations; using LibrarySystem.Application.Catalog; using LibrarySystem.Application.Security; using LibrarySystem.Domain.Catalog; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore;
namespace LibrarySystem.Pages.Dashboards; [Authorize(Policy=PolicyNames.ManageCatalog)] public sealed class AcquisitionsModel(IAcquisitionService service,ICatalogService catalog,ICatalogReferenceService refs):PageModel { [BindProperty(SupportsGet=true)] public int Year{get;set;}=DateTime.Today.Year; public IReadOnlyCollection<AcquisitionDto> Records{get;private set;}=[]; public IReadOnlyCollection<BookDto> Books{get;private set;}=[]; public IReadOnlyCollection<CatalogReferenceDto> Shelves{get;private set;}=[]; public AcquisitionBudgetDto Budget{get;private set;}=null!; public async Task OnGetAsync(CancellationToken token)=>await Load(token); public Task<IActionResult> OnPostCreateAsync(string orderNumber,long bookId,AcquisitionSource source,string? donationSource,int quantity,decimal unitCost,CancellationToken token)=>Run(async()=>{await service.CreateAsync(orderNumber,bookId,source,donationSource,quantity,unitCost,token);},"Acquisition record created."); public Task<IActionResult> OnPostReceiveAsync(long id,string barcode,int? shelfId,string rowVersion,CancellationToken token)=>Run(async()=>await service.ReceiveAsync(id,barcode,shelfId,Convert.FromBase64String(rowVersion),token),"Material received and physical copy created."); public Task<IActionResult> OnPostStatusAsync(long id,AcquisitionStatus status,string rowVersion,CancellationToken token)=>Run(async()=>await service.SetStatusAsync(id,status,Convert.FromBase64String(rowVersion),token),"Record status updated."); public Task<IActionResult> OnPostBudgetAsync(int year,decimal amount,CancellationToken token)=>Run(async()=>await service.SetBudgetAsync(year,amount,token),"Budget updated."); private async Task<IActionResult> Run(Func<Task> action,string message){try{await action();TempData["StatusMessage"]=message;}catch(FormatException){TempData["ErrorMessage"]="The concurrency token is invalid.";}catch(Exception e)when(e is ValidationException or DbUpdateException or KeyNotFoundException){TempData["ErrorMessage"]=e is DbUpdateException?"The reference number or barcode conflicts with an existing record.":e.Message;}return RedirectToPage(new{Year});} private async Task Load(CancellationToken token){Records=await service.ListAsync(token);Books=(await catalog.SearchAsync(new CatalogSearchRequest{PageNumber=1,PageSize=100},token)).Items;Shelves=await refs.GetShelvesAsync(token);Budget=await service.GetBudgetAsync(Year,token);} }
